function drawEmfA432Field(ctx, w, h, atMs, hue2 = A432_HUE) {
  ctx.clearRect(0, 0, w, h);
  const cx = w / 2, cy = h / 2;
  const maxR = Math.min(w, h) * 0.46;
  const shellFreqs = [60, 120, 7e8, 35e8, 24e8, 58e8];
  shellFreqs.forEach((f, i) => {
    const r = maxR * (0.18 + 0.8 * (i + 1) / shellFreqs.length);
    ctx.strokeStyle = `hsla(${frequencyToLight(f).hue}, 60%, 60%, 0.10)`;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.stroke();
  });
  ctx.fillStyle = "rgba(255,255,255,0.08)";
  const dw = maxR * 0.34, dh = maxR * 0.6;
  ctx.fillRect(cx - dw / 2, cy - dh / 2, dw, dh);
  const breath = humanBreath(atMs, 6e3);
  const pulseR = maxR * 0.55 * breath;
  ctx.strokeStyle = `hsla(${hue2}, 85%, 62%, 0.6)`;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(cx, cy, pulseR, 0, Math.PI * 2);
  ctx.stroke();
  VORTEX_SEQUENCE.forEach((d, i) => {
    const ang = i / VORTEX_SEQUENCE.length * Math.PI * 2 + atMs / 4e3;
    const rr = pulseR * (0.55 + d / 18);
    const x = cx + Math.cos(ang) * rr, y = cy + Math.sin(ang) * rr;
    ctx.fillStyle = `hsla(${(hue2 + d * 8) % 360}, 80%, 65%, ${0.35 + 0.4 * (breath - 0.82)})`;
    ctx.beginPath();
    ctx.arc(x, y, 3 + d * 0.6, 0, Math.PI * 2);
    ctx.fill();
  });
}
