var A432_HZ = 432;
function a432NoteHz(semitonesFromA) {
  return A432_HZ * 2 ** (semitonesFromA / 12);
}
function a432Semitones(hz) {
  return 12 * Math.log2(Math.max(hz, 1) / A432_HZ);
}
function colorFromSound2(frequency) {
  const ref = a432NoteHz(-21);
  const octaveFraction = (Math.log2(Math.max(frequency, 1) / ref) % 1 + 1) % 1;
  const hue2 = Math.round(octaveFraction * 360);
  return { frequency, hue: hue2, hsl: movieCanvasHex(hue2, { L: 11 / 16 }) };
}
function soundFromColor(hue2, octave = 4) {
  const ref = a432NoteHz(-21);
  const normalizedHue = (Math.round(hue2) % 360 + 360) % 360;
  const octaveFraction = normalizedHue / 360;
  const frequency = ref * 2 ** (octave + octaveFraction);
  return {
    hue: normalizedHue,
    frequency: roundTo(frequency, 4),
    octave,
    audible: frequency >= 20 && frequency <= 2e4,
    hz: roundTo(frequency, 2)
  };
}
